def shortest_path(graph, source, target):
    # Function to get the neighbors and their weights from the graph
    def neighbors(node):
        return graph[node]

    # Dijkstra's algorithm
    def dijkstra(graph, source):
        distances = {node: float('inf') for node in graph}
        distances[source] = 0
        queue = [(0, source)]

        while queue:
            current_distance, current_node = heapq.heappop(queue)

            # If we reached the target, we can return the distance and the path
            if current_node == target:
                path = [current_node]
                while current_node != source:
                    for neighbor, weight in neighbors(current_node):
                        if distances[neighbor] == distances[current_node] - weight:
                            path.append(neighbor)
                            current_node = neighbor
                            break
                return distances[target], path[::-1]

            # Only iterate through the neighbors if we have not already processed the neighbor with a shorter distance
            if current_distance < distances[current_node]:
                for neighbor, weight in neighbors(current_node):
                    new_distance = current_distance + weight
                    if new_distance < distances[neighbor]:
                        distances[neighbor] = new_distance
